      // Detect unsafe eval usage
      const patterns = [
        /eval\s*\(/g,
        /new\s+Function\s*\(/g,
        /setTimeout\s*\(\s*["']/g,
        /setInterval\s*\(\s*["']/g
      ];
    `,
    remediation: `
