}

/**
 * Helper to create a text message
 */
export function textMessage(
  role: 'user' | 'assistant',
  text: string
): PromptMessage {
  return {
    role,
    content: {
      type: 'text',
      text,
    } as TextContent,
  };
}

/**
 * Helper to create a message with embedded resource
 */
export function resourceMessage(
  role: 'user' | 'assistant',
  resource: ResourceContent
): PromptMessage {
  return {
    role,
    content: {
      type: 'resource',
      resource,
    } as EmbeddedResource,
  };
}

/**
 * Template string interpolation for prompts
 */
export function interpolate(
  template: string,
  args: Record<string, string>
): string {
  return template.replace(/\{(\w+)\}/g, (match, key) => {
    return args[key] ?? match;
  });
}

/**
 * @claude-flow/mcp - Rate Limiter
 *
 * Token bucket rate limiting for DoS protection
 */

import { EventEmitter } from 'events';
import type { ILogger } from './types.js';

export interface RateLimitConfig {
  /** Requests per second */
  requestsPerSecond: number;
  /** Burst size (max tokens) */
  burstSize: number;
  /** Per-session limits (if different from global) */
  perSessionLimit?: number;
  /** Cleanup interval for expired sessions */
  cleanupInterval?: number;
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetIn: number; // ms until bucket refills
  retryAfter?: number; // seconds to wait (for 429 response)
}

interface TokenBucket {
  tokens: number;
  lastRefill: number;
}

const DEFAULT_CONFIG: RateLimitConfig = {
  requestsPerSecond: 100,
  burstSize: 200,
  perSessionLimit: 50,
  cleanupInterval: 60000, // 1 minute
};

export class RateLimiter extends EventEmitter {
  private readonly config: Required<RateLimitConfig>;
  private globalBucket: TokenBucket;
  private sessionBuckets: Map<string, TokenBucket> = new Map();
  private cleanupTimer?: NodeJS.Timeout;

  constructor(
    private readonly logger: ILogger,
    config: Partial<RateLimitConfig> = {}
  ) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config } as Required<RateLimitConfig>;

    // Initialize global bucket
    this.globalBucket = {
      tokens: this.config.burstSize,
      lastRefill: Date.now(),
    };

    this.startCleanup();
  }

  /**
   * Check if request is allowed (global limit)
   */
  checkGlobal(): RateLimitResult {
    return this.checkBucket(this.globalBucket, this.config.requestsPerSecond, this.config.burstSize);
  }

  /**
   * Check if request is allowed (per-session limit)
   */
  checkSession(sessionId: string): RateLimitResult {
    let bucket = this.sessionBuckets.get(sessionId);
    if (!bucket) {
      bucket = {
        tokens: this.config.perSessionLimit,
        lastRefill: Date.now(),
      };
      this.sessionBuckets.set(sessionId, bucket);
    }

    return this.checkBucket(
      bucket,
      this.config.perSessionLimit / 10, // Refill rate (10 seconds to full)
      this.config.perSessionLimit
    );
  }

  /**
   * Check both global and session limits
   */
  check(sessionId?: string): RateLimitResult {
    const globalResult = this.checkGlobal();
    if (!globalResult.allowed) {
      this.emit('rate-limit:global', { remaining: globalResult.remaining });
      return globalResult;
    }

    if (sessionId) {
      const sessionResult = this.checkSession(sessionId);
      if (!sessionResult.allowed) {
        this.emit('rate-limit:session', { sessionId, remaining: sessionResult.remaining });
        return sessionResult;
      }
      return sessionResult;
    }

    return globalResult;
  }

  /**
   * Consume a token (call after request is processed)
   */
  consume(sessionId?: string): void {
    this.consumeFromBucket(this.globalBucket);
    if (sessionId) {
      const bucket = this.sessionBuckets.get(sessionId);
      if (bucket) {
        this.consumeFromBucket(bucket);
      }
    }
  }

  /**
   * Reset session bucket
   */
  resetSession(sessionId: string): void {
    this.sessionBuckets.delete(sessionId);
    this.logger.debug('Rate limit session reset', { sessionId });
  }

  /**
   * Get current stats
   */
  getStats(): {
    globalTokens: number;
    globalBurstSize: number;
    sessionCount: number;
    config: RateLimitConfig;
  } {
    this.refillBucket(this.globalBucket, this.config.requestsPerSecond, this.config.burstSize);
    return {
      globalTokens: Math.floor(this.globalBucket.tokens),
      globalBurstSize: this.config.burstSize,
      sessionCount: this.sessionBuckets.size,
      config: this.config,
    };
  }

  /**
   * Destroy the rate limiter
   */
  destroy(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = undefined;
    }
    this.sessionBuckets.clear();
    this.removeAllListeners();
  }

  /**
   * Check bucket and refill tokens
   */
  private checkBucket(
    bucket: TokenBucket,
    refillRate: number,
    maxTokens: number
  ): RateLimitResult {
    this.refillBucket(bucket, refillRate, maxTokens);

    if (bucket.tokens >= 1) {
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens) - 1,
        resetIn: Math.ceil((maxTokens - bucket.tokens) / refillRate * 1000),
      };
    }

    // Calculate when bucket will have 1 token
    const tokensNeeded = 1 - bucket.tokens;
    const retryAfter = Math.ceil(tokensNeeded / refillRate);

    return {
      allowed: false,
      remaining: 0,
      resetIn: retryAfter * 1000,
      retryAfter,
    };
  }

  /**
   * Refill tokens based on elapsed time
   */
  private refillBucket(bucket: TokenBucket, refillRate: number, maxTokens: number): void {
    const now = Date.now();
    const elapsed = (now - bucket.lastRefill) / 1000; // seconds
    const tokensToAdd = elapsed * refillRate;

    bucket.tokens = Math.min(maxTokens, bucket.tokens + tokensToAdd);
    bucket.lastRefill = now;
  }

  /**
   * Consume a token from bucket
   */
  private consumeFromBucket(bucket: TokenBucket): void {
    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
    }
  }

  /**
   * Start cleanup timer for expired sessions
   */
  private startCleanup(): void {
    this.cleanupTimer = setInterval(() => {
      const now = Date.now();
      const expireTime = this.config.cleanupInterval * 2;

      for (const [sessionId, bucket] of this.sessionBuckets) {
        if (now - bucket.lastRefill > expireTime) {
          this.sessionBuckets.delete(sessionId);
          this.logger.debug('Rate limit session expired', { sessionId });
        }
      }
    }, this.config.cleanupInterval);
  }
}

export function createRateLimiter(
  logger: ILogger,
  config?: Partial<RateLimitConfig>
): RateLimiter {
  return new RateLimiter(logger, config);
}

/**
 * Express/Connect middleware for rate limiting
 */
export function rateLimitMiddleware(rateLimiter: RateLimiter) {
  return (req: any, res: any, next: () => void) => {
    const sessionId = req.headers['x-session-id'] || req.ip;
    const result = rateLimiter.check(sessionId);

    res.setHeader('X-RateLimit-Remaining', result.remaining);
    res.setHeader('X-RateLimit-Reset', Math.ceil(Date.now() / 1000) + Math.ceil(result.resetIn / 1000));

    if (!result.allowed) {
      res.setHeader('Retry-After', result.retryAfter);
      res.status(429).json({
        jsonrpc: '2.0',
        id: null,
        error: {
          code: -32000,
          message: 'Rate limit exceeded',
          data: { retryAfter: result.retryAfter },
        },
      });
      return;
    }

    rateLimiter.consume(sessionId);
    next();
  };
}

/**
 * @claude-flow/mcp - Resource Registry
 *
 * MCP 2025-11-25 compliant resource management
 * Supports: list, read, subscribe, templates, pagination
 */

import { EventEmitter } from 'events';
import type {
  MCPResource,
  ResourceContent,
  ResourceTemplate,
  ResourceListResult,
  ResourceReadResult,
  ILogger,
  ContentAnnotations,
} from './types.js';

export type ResourceHandler = (uri: string) => Promise<ResourceContent[]>;
export type SubscriptionCallback = (uri: string, content: ResourceContent[]) => void;

export interface ResourceRegistryOptions {
  enableSubscriptions?: boolean;
  maxSubscriptionsPerResource?: number;
  cacheEnabled?: boolean;
  cacheTTL?: number;
  maxCacheSize?: number; // SECURITY: Prevent unbounded cache growth
}

interface CachedResource {
  content: ResourceContent[];
  cachedAt: number;
  ttl: number;
}

interface Subscription {
  id: string;
  uri: string;
  callback: SubscriptionCallback;
  createdAt: Date;
}

export class ResourceRegistry extends EventEmitter {
  private resources: Map<string, MCPResource> = new Map();
  private templates: Map<string, ResourceTemplate> = new Map();
  private handlers: Map<string, ResourceHandler> = new Map();
  private subscriptions: Map<string, Subscription[]> = new Map();
  private cache: Map<string, CachedResource> = new Map();
  private subscriptionCounter = 0;

  private readonly options: Required<ResourceRegistryOptions>;

  constructor(
    private readonly logger: ILogger,
    options: ResourceRegistryOptions = {}
  ) {
    super();
    this.options = {
      enableSubscriptions: options.enableSubscriptions ?? true,
      maxSubscriptionsPerResource: options.maxSubscriptionsPerResource ?? 100,
      cacheEnabled: options.cacheEnabled ?? true,
      cacheTTL: options.cacheTTL ?? 60000, // 1 minute default
      maxCacheSize: options.maxCacheSize ?? 1000, // SECURITY: Default max 1000 entries
    };
  }

  /**
   * Register a static resource
   */
  registerResource(resource: MCPResource, handler: ResourceHandler): boolean {
    if (this.resources.has(resource.uri)) {
      this.logger.warn('Resource already registered', { uri: resource.uri });
      return false;
    }

    this.resources.set(resource.uri, resource);
    this.handlers.set(resource.uri, handler);

    this.logger.debug('Resource registered', { uri: resource.uri, name: resource.name });
    this.emit('resource:registered', { uri: resource.uri });
    this.emitListChanged();

    return true;
  }

  /**
   * Register a resource template (dynamic URIs)
   */
  registerTemplate(template: ResourceTemplate, handler: ResourceHandler): boolean {
    if (this.templates.has(template.uriTemplate)) {
      this.logger.warn('Template already registered', { template: template.uriTemplate });
      return false;
    }

    this.templates.set(template.uriTemplate, template);
    this.handlers.set(template.uriTemplate, handler);

    this.logger.debug('Resource template registered', { template: template.uriTemplate });
    this.emit('template:registered', { template: template.uriTemplate });

    return true;
  }

  /**
   * Unregister a resource
   */
  unregisterResource(uri: string): boolean {
    if (!this.resources.has(uri)) {
      return false;
    }

    this.resources.delete(uri);
    this.handlers.delete(uri);
    this.cache.delete(uri);

    // Cancel subscriptions for this resource
    const subs = this.subscriptions.get(uri) || [];
    for (const sub of subs) {
      this.emit('subscription:cancelled', { subscriptionId: sub.id, uri });
    }
    this.subscriptions.delete(uri);

    this.logger.debug('Resource unregistered', { uri });
    this.emit('resource:unregistered', { uri });
    this.emitListChanged();

    return true;
  }

  /**
   * List resources with pagination
   */
  list(cursor?: string, pageSize: number = 50): ResourceListResult {
    const allResources = Array.from(this.resources.values());

    let startIndex = 0;
    if (cursor) {
      const decoded = this.decodeCursor(cursor);
      startIndex = decoded.offset;
    }

    const endIndex = Math.min(startIndex + pageSize, allResources.length);
    const resources = allResources.slice(startIndex, endIndex);

    const result: ResourceListResult = { resources };

    if (endIndex < allResources.length) {
      result.nextCursor = this.encodeCursor({ offset: endIndex });
    }

    return result;
  }

  /**
   * Read resource content
   */
  async read(uri: string): Promise<ResourceReadResult> {
    // Check cache first
    if (this.options.cacheEnabled) {
      const cached = this.cache.get(uri);
      if (cached && Date.now() - cached.cachedAt < cached.ttl) {
        this.logger.debug('Resource cache hit', { uri });
        return { contents: cached.content };
      }
    }

    // Find handler (exact match or template match)
    let handler = this.handlers.get(uri);
    if (!handler) {
      handler = this.findTemplateHandler(uri);
    }

    if (!handler) {
      throw new Error(`Resource not found: ${uri}`);
    }

    const contents = await handler(uri);

    // Cache the result with size limit (LRU eviction)
    if (this.options.cacheEnabled) {
      // SECURITY: Enforce max cache size to prevent memory exhaustion
      if (this.cache.size >= this.options.maxCacheSize) {
        // Remove oldest entry (first entry in Map iteration order)
        const oldestKey = this.cache.keys().next().value;
        if (oldestKey) {
          this.cache.delete(oldestKey);
          this.logger.debug('Cache evicted oldest entry', { uri: oldestKey });
        }
      }

      this.cache.set(uri, {
        content: contents,
        cachedAt: Date.now(),
        ttl: this.options.cacheTTL,
      });
    }

    this.emit('resource:read', { uri, contentCount: contents.length });
    return { contents };
  }

  /**
   * Subscribe to resource updates
   */
  subscribe(uri: string, callback: SubscriptionCallback): string {
    if (!this.options.enableSubscriptions) {
      throw new Error('Subscriptions are disabled');
    }

    const existingSubs = this.subscriptions.get(uri) || [];
    if (existingSubs.length >= this.options.maxSubscriptionsPerResource) {
      throw new Error(`Maximum subscriptions reached for resource: ${uri}`);
    }

    const subscriptionId = `sub-${++this.subscriptionCounter}-${Date.now()}`;
    const subscription: Subscription = {
      id: subscriptionId,
      uri,
      callback,
      createdAt: new Date(),
    };

    existingSubs.push(subscription);
    this.subscriptions.set(uri, existingSubs);

    this.logger.debug('Subscription created', { subscriptionId, uri });
    this.emit('subscription:created', { subscriptionId, uri });

    return subscriptionId;
  }

  /**
   * Unsubscribe from resource updates
   */
  unsubscribe(subscriptionId: string): boolean {
    for (const [uri, subs] of this.subscriptions) {
      const index = subs.findIndex((s) => s.id === subscriptionId);
      if (index !== -1) {
        subs.splice(index, 1);
        if (subs.length === 0) {
          this.subscriptions.delete(uri);
        }
        this.logger.debug('Subscription removed', { subscriptionId, uri });
        this.emit('subscription:removed', { subscriptionId, uri });
        return true;
      }
    }
    return false;
  }

  /**
   * Notify subscribers of resource update
   */
  async notifyUpdate(uri: string): Promise<void> {
    const subs = this.subscriptions.get(uri);
    if (!subs || subs.length === 0) {
      return;
    }

    // Invalidate cache
    this.cache.delete(uri);

    // Read fresh content
    const { contents } = await this.read(uri);

    // Notify all subscribers
    for (const sub of subs) {
      try {
        sub.callback(uri, contents);
      } catch (error) {
        this.logger.error('Subscription callback error', { subscriptionId: sub.id, error });
      }
    }

    this.emit('resource:updated', { uri, subscriberCount: subs.length });
  }

  /**
   * Get resource by URI
   */
  getResource(uri: string): MCPResource | undefined {
    return this.resources.get(uri);
  }

  /**
   * Check if resource exists
   */
  hasResource(uri: string): boolean {
    return this.resources.has(uri) || this.matchesTemplate(uri);
  }

  /**
   * Get resource count
   */
  getResourceCount(): number {
    return this.resources.size;
  }

  /**
   * Get all templates
   */
  getTemplates(): ResourceTemplate[] {
    return Array.from(this.templates.values());
  }

  /**
   * Get subscription count for a resource
   */
  getSubscriptionCount(uri: string): number {
    return this.subscriptions.get(uri)?.length || 0;
  }

  /**
   * Get stats
   */
  getStats(): {
    totalResources: number;
    totalTemplates: number;
    totalSubscriptions: number;
    cacheSize: number;
  } {
    let totalSubscriptions = 0;
    for (const subs of this.subscriptions.values()) {
      totalSubscriptions += subs.length;
    }

    return {
      totalResources: this.resources.size,
      totalTemplates: this.templates.size,
      totalSubscriptions,
      cacheSize: this.cache.size,
    };
  }

  /**
   * Clear cache
   */
  clearCache(): void {
    this.cache.clear();
    this.logger.debug('Resource cache cleared');
  }

  /**
   * Find handler for template URI
   */
  private findTemplateHandler(uri: string): ResourceHandler | undefined {
    for (const [template, handler] of this.handlers) {
      if (this.matchesTemplate(uri, template)) {
        return handler;
      }
    }
    return undefined;
  }

  /**
   * Escape regex metacharacters to prevent ReDoS attacks
   * SECURITY: Critical for preventing regex denial of service
   */
  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  /**
   * Check if URI matches any template
   * SECURITY: Uses escaped regex to prevent ReDoS
   */
  private matchesTemplate(uri: string, template?: string): boolean {
    if (template) {
      // SECURITY: Escape regex metacharacters before converting template
      // First extract placeholders, escape the rest, then add placeholder pattern
      const escaped = this.escapeRegex(template);
      // Replace escaped placeholder braces with the pattern
      const pattern = escaped.replace(/\\\{[^}]+\\\}/g, '[^/]+');
      try {
        const regex = new RegExp('^' + pattern + '$');
        return regex.test(uri);
      } catch {
        // Invalid regex pattern - return false safely
        return false;
      }
    }

    for (const t of this.templates.keys()) {
      const escaped = this.escapeRegex(t);
      const pattern = escaped.replace(/\\\{[^}]+\\\}/g, '[^/]+');
      try {
        const regex = new RegExp('^' + pattern + '$');
        if (regex.test(uri)) {
          return true;
        }
      } catch {
        // Skip invalid patterns
        continue;
      }
    }
    return false;
  }

  /**
   * Encode cursor for pagination
   */
  private encodeCursor(data: { offset: number }): string {
    return Buffer.from(JSON.stringify(data)).toString('base64');
  }

  /**
   * Decode cursor for pagination
   */
  private decodeCursor(cursor: string): { offset: number } {
    try {
      return JSON.parse(Buffer.from(cursor, 'base64').toString('utf-8'));
    } catch {
      return { offset: 0 };
    }
  }

  /**
   * Emit listChanged notification
   */
  private emitListChanged(): void {
    this.emit('resources:listChanged');
  }
}

export function createResourceRegistry(
  logger: ILogger,
  options?: ResourceRegistryOptions
): ResourceRegistry {
  return new ResourceRegistry(logger, options);
}

/**
 * Helper to create a static text resource
 */
export function createTextResource(
  uri: string,
  name: string,
  text: string,
  options?: {
    description?: string;
    mimeType?: string;
    annotations?: ContentAnnotations;
  }
): { resource: MCPResource; handler: ResourceHandler } {
  const resource: MCPResource = {
    uri,
    name,
    description: options?.description,
    mimeType: options?.mimeType || 'text/plain',
    annotations: options?.annotations,
  };

  const handler: ResourceHandler = async () => [
    {
      uri,
      mimeType: options?.mimeType || 'text/plain',
      text,
    },
  ];

  return { resource, handler };
}

/**
 * Helper to create a file resource
 * SECURITY: Validates path to prevent path traversal attacks
 */
export function createFileResource(
  uri: string,
  name: string,
  filePath: string,
  options?: {
    description?: string;
    mimeType?: string;
    allowedBasePaths?: string[]; // Security: restrict to these base paths
  }
): { resource: MCPResource; handler: ResourceHandler } {
  const resource: MCPResource = {
    uri,
    name,
    description: options?.description,
    mimeType: options?.mimeType || 'application/octet-stream',
  };

  const handler: ResourceHandler = async () => {
    const fs = await import('fs/promises');
    const path = await import('path');

    // SECURITY: Normalize and validate the path
    const normalizedPath = path.normalize(filePath);

    // Prevent path traversal
    if (normalizedPath.includes('..') || normalizedPath.includes('\0')) {
      throw new Error('Invalid file path: path traversal detected');
    }

    // Prevent access to sensitive system paths
    const blockedPaths = ['/etc/', '/proc/', '/sys/', '/dev/', '/root/', '/var/log/'];
    const lowerPath = normalizedPath.toLowerCase();
    for (const blocked of blockedPaths) {
      if (lowerPath.startsWith(blocked) || lowerPath.includes('/.')) {
        throw new Error('Access to system paths is not allowed');
      }
    }

    // If allowedBasePaths specified, validate against them
    if (options?.allowedBasePaths && options.allowedBasePaths.length > 0) {
      const resolvedPath = path.resolve(normalizedPath);
      const isAllowed = options.allowedBasePaths.some((basePath) => {
        const resolvedBase = path.resolve(basePath);
        return resolvedPath.startsWith(resolvedBase);
      });

      if (!isAllowed) {
        throw new Error('File path is outside allowed directories');
      }
    }

    const content = await fs.readFile(normalizedPath);
    return [
      {
        uri,
        mimeType: options?.mimeType || 'application/octet-stream',
        blob: content.toString('base64'),
      },
    ];
  };

  return { resource, handler };
}

/**
 * @claude-flow/mcp - Sampling (Server-Initiated LLM)
 *
 * MCP 2025-11-25 compliant sampling for server-initiated LLM calls
 */

import { EventEmitter } from 'events';
import type {
  SamplingMessage,
  ModelPreferences,
  CreateMessageRequest,
  CreateMessageResult,
  PromptContent,
  ILogger,
} from './types.js';

/**
 * External LLM provider interface
 */
export interface LLMProvider {
  name: string;
  createMessage(request: CreateMessageRequest): Promise<CreateMessageResult>;
  isAvailable(): Promise<boolean>;
}

/**
 * Sampling configuration
 */
export interface SamplingConfig {
  /** Default model preferences */
  defaultModelPreferences?: ModelPreferences;
  /** Maximum tokens for any request */
  maxTokensLimit?: number;
  /** Default temperature */
  defaultTemperature?: number;
  /** Timeout for LLM calls (ms) */
  timeout?: number;
  /** Enable request logging */
  enableLogging?: boolean;
}

/**
 * Sampling request context
 */
export interface SamplingContext {
  sessionId: string;
  serverId?: string;
  metadata?: Record<string, unknown>;
}

const DEFAULT_CONFIG: Required<SamplingConfig> = {
  defaultModelPreferences: {
    intelligencePriority: 0.5,
    speedPriority: 0.3,
    costPriority: 0.2,
  },
  maxTokensLimit: 4096,
  defaultTemperature: 0.7,
  timeout: 30000,
  enableLogging: true,
};

export class SamplingManager extends EventEmitter {
  private readonly config: Required<SamplingConfig>;
  private providers: Map<string, LLMProvider> = new Map();
  private defaultProvider?: string;
  private requestCount = 0;
  private totalTokens = 0;

  constructor(
    private readonly logger: ILogger,
    config: Partial<SamplingConfig> = {}
  ) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Register an LLM provider
   */
  registerProvider(provider: LLMProvider, isDefault: boolean = false): void {
    this.providers.set(provider.name, provider);
    if (isDefault || !this.defaultProvider) {
      this.defaultProvider = provider.name;
    }
    this.logger.info('LLM provider registered', { name: provider.name, isDefault });
    this.emit('provider:registered', { name: provider.name });
  }

  /**
   * Unregister a provider
   */
  unregisterProvider(name: string): boolean {
    const removed = this.providers.delete(name);
    if (removed && this.defaultProvider === name) {
      this.defaultProvider = this.providers.keys().next().value;
    }
    return removed;
  }

  /**
   * Create a message (sampling/createMessage)
   */
  async createMessage(
    request: CreateMessageRequest,
    context?: SamplingContext
  ): Promise<CreateMessageResult> {
    const startTime = Date.now();
    this.requestCount++;

    // Validate request
    this.validateRequest(request);

    // Select provider
    const provider = this.selectProvider(request.modelPreferences);
    if (!provider) {
      throw new Error('No LLM provider available');
    }

    // Apply defaults
    const fullRequest = this.applyDefaults(request);

    if (this.config.enableLogging) {
      this.logger.debug('Sampling request', {
        provider: provider.name,
        messageCount: request.messages.length,
        maxTokens: fullRequest.maxTokens,
        sessionId: context?.sessionId,
      });
    }

    this.emit('sampling:start', { provider: provider.name, context });

    try {
      // Call provider with timeout
      const result = await this.callWithTimeout(
        provider.createMessage(fullRequest),
        this.config.timeout
      );

      const duration = Date.now() - startTime;

      if (this.config.enableLogging) {
        this.logger.info('Sampling complete', {
          provider: provider.name,
          duration: `${duration}ms`,
          stopReason: result.stopReason,
        });
      }

      this.emit('sampling:complete', {
        provider: provider.name,
        duration,
        result,
        context,
      });

      return result;
    } catch (error) {
      const duration = Date.now() - startTime;

      this.logger.error('Sampling failed', {
        provider: provider.name,
        duration: `${duration}ms`,
        error,
      });

      this.emit('sampling:error', {
        provider: provider.name,
        duration,
        error,
        context,
      });

      throw error;
    }
  }

  /**
   * Check if sampling is available
   */
  async isAvailable(): Promise<boolean> {
    if (this.providers.size === 0) {
      return false;
    }

    for (const provider of this.providers.values()) {
      if (await provider.isAvailable()) {
        return true;
      }
    }

    return false;
  }

  /**
   * Get available providers
   */
  getProviders(): string[] {
    return Array.from(this.providers.keys());
  }

  /**
   * Get stats
   */
  getStats(): {
    requestCount: number;
    totalTokens: number;
    providerCount: number;
    defaultProvider?: string;
  } {
    return {
      requestCount: this.requestCount,
      totalTokens: this.totalTokens,
      providerCount: this.providers.size,
      defaultProvider: this.defaultProvider,
    };
  }

  /**
   * Validate sampling request
   */
  private validateRequest(request: CreateMessageRequest): void {
    if (!request.messages || request.messages.length === 0) {
      throw new Error('Messages are required');
    }

    if (request.maxTokens > this.config.maxTokensLimit) {
      throw new Error(`maxTokens exceeds limit of ${this.config.maxTokensLimit}`);
    }

    if (request.temperature !== undefined && (request.temperature < 0 || request.temperature > 2)) {
      throw new Error('Temperature must be between 0 and 2');
    }
  }

  /**
   * Select provider based on preferences
   */
  private selectProvider(preferences?: ModelPreferences): LLMProvider | undefined {
    // If hints provided, try to find matching provider
    if (preferences?.hints) {
      for (const hint of preferences.hints) {
        if (hint.name && this.providers.has(hint.name)) {
          return this.providers.get(hint.name);
        }
      }
    }

    // Use default provider
    if (this.defaultProvider) {
      return this.providers.get(this.defaultProvider);
    }

    // Return first available
    return this.providers.values().next().value;
  }

  /**
   * Apply default values to request
   */
  private applyDefaults(request: CreateMessageRequest): CreateMessageRequest {
    return {
      ...request,
      modelPreferences: request.modelPreferences || this.config.defaultModelPreferences,
      temperature: request.temperature ?? this.config.defaultTemperature,
      maxTokens: Math.min(request.maxTokens, this.config.maxTokensLimit),
    };
  }

  /**
   * Call with timeout
   */
  private async callWithTimeout<T>(promise: Promise<T>, timeout: number): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) => {
        setTimeout(() => reject(new Error('Sampling timeout')), timeout);
      }),
    ]);
  }
}

export function createSamplingManager(
  logger: ILogger,
  config?: Partial<SamplingConfig>
): SamplingManager {
  return new SamplingManager(logger, config);
}

/**
 * Create a mock LLM provider for testing
 */
export function createMockProvider(name: string = 'mock'): LLMProvider {
  return {
    name,
    async createMessage(request: CreateMessageRequest): Promise<CreateMessageResult> {
      // Mock provider response delay
      await new Promise((r) => setTimeout(r, 100));

      return {
        role: 'assistant',
        content: {
          type: 'text',
          text: `Mock response to: ${JSON.stringify(request.messages[0]?.content)}`,
        },
        model: `${name}-model`,
        stopReason: 'endTurn',
      };
    },
    async isAvailable(): Promise<boolean> {
      return true;
    },
  };
}

/**
 * Create an Anthropic provider (requires API key)
 */
export function createAnthropicProvider(apiKey: string): LLMProvider {
  return {
    name: 'anthropic',
    async createMessage(request: CreateMessageRequest): Promise<CreateMessageResult> {
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
        },
        body: JSON.stringify({
          model: 'claude-3-haiku-20240307',
          max_tokens: request.maxTokens,
          temperature: request.temperature,
          system: request.systemPrompt,
          messages: request.messages.map((m) => ({
            role: m.role,
            content: m.content.type === 'text' ? (m.content as any).text : m.content,
          })),
        }),
      });

      if (!response.ok) {
        throw new Error(`Anthropic API error: ${response.status}`);
      }

      const data = await response.json() as any;

      return {
        role: 'assistant',
        content: {
          type: 'text',
          text: data.content[0]?.text || '',
        },
        model: data.model,
        stopReason: data.stop_reason === 'end_turn' ? 'endTurn' : 'maxTokens',
      };
    },
    async isAvailable(): Promise<boolean> {
      return !!apiKey;
    },
  };
}

/**
 * @claude-flow/mcp - JSON Schema Validator
 *
 * Lightweight JSON Schema validation for tool inputs
 * Implements JSON Schema Draft 2020-12 subset
 */

import type { JSONSchema } from './types.js';

export interface ValidationError {
  path: string;
  message: string;
  keyword: string;
  params?: Record<string, unknown>;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validate data against JSON Schema
 */
export function validateSchema(
  data: unknown,
  schema: JSONSchema,
  path: string = ''
): ValidationResult {
  const errors: ValidationError[] = [];

  // Type validation
  if (schema.type) {
    const typeValid = validateType(data, schema.type);
    if (!typeValid) {
      errors.push({
        path: path || 'root',
        message: `Expected type "${schema.type}", got "${typeof data}"`,
        keyword: 'type',
        params: { expected: schema.type, actual: typeof data },
      });
      return { valid: false, errors };
    }
  }

  // Null check
  if (data === null || data === undefined) {
    if (schema.type && schema.type !== 'null') {
      errors.push({
        path: path || 'root',
        message: 'Value cannot be null or undefined',
        keyword: 'type',
      });
    }
    return { valid: errors.length === 0, errors };
  }

  // String validations
  if (schema.type === 'string' && typeof data === 'string') {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      errors.push({
        path,
        message: `String length must be >= ${schema.minLength}`,
        keyword: 'minLength',
        params: { limit: schema.minLength, actual: data.length },
      });
    }
    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      errors.push({
        path,
        message: `String length must be <= ${schema.maxLength}`,
        keyword: 'maxLength',
        params: { limit: schema.maxLength, actual: data.length },
      });
    }
    if (schema.pattern) {
      const regex = new RegExp(schema.pattern);
      if (!regex.test(data)) {
        errors.push({
          path,
          message: `String must match pattern "${schema.pattern}"`,
          keyword: 'pattern',
          params: { pattern: schema.pattern },
        });
      }
    }
    if (schema.enum && !schema.enum.includes(data)) {
      errors.push({
        path,
        message: `Value must be one of: ${schema.enum.join(', ')}`,
        keyword: 'enum',
        params: { allowedValues: schema.enum },
      });
    }
  }

  // Number validations
  if ((schema.type === 'number' || schema.type === 'integer') && typeof data === 'number') {
    if (schema.type === 'integer' && !Number.isInteger(data)) {
      errors.push({
        path,
        message: 'Value must be an integer',
        keyword: 'type',
      });
    }
    if (schema.minimum !== undefined && data < schema.minimum) {
      errors.push({
        path,
        message: `Value must be >= ${schema.minimum}`,
        keyword: 'minimum',
        params: { limit: schema.minimum, actual: data },
      });
    }
    if (schema.maximum !== undefined && data > schema.maximum) {
      errors.push({
        path,
        message: `Value must be <= ${schema.maximum}`,
        keyword: 'maximum',
        params: { limit: schema.maximum, actual: data },
      });
    }
  }

  // Array validations
  if (schema.type === 'array' && Array.isArray(data)) {
    if (schema.items) {
      for (let i = 0; i < data.length; i++) {
        const itemResult = validateSchema(data[i], schema.items, `${path}[${i}]`);
        errors.push(...itemResult.errors);
      }
    }
  }

  // Object validations
  if (schema.type === 'object' && typeof data === 'object' && !Array.isArray(data)) {
    const obj = data as Record<string, unknown>;

    // Required properties
    if (schema.required) {
      for (const requiredProp of schema.required) {
        if (!(requiredProp in obj)) {
          errors.push({
            path: path ? `${path}.${requiredProp}` : requiredProp,
            message: `Required property "${requiredProp}" is missing`,
            keyword: 'required',
            params: { missingProperty: requiredProp },
          });
        }
      }
    }

    // Property validations
    if (schema.properties) {
      for (const [propName, propSchema] of Object.entries(schema.properties)) {
        if (propName in obj) {
          const propPath = path ? `${path}.${propName}` : propName;
          const propResult = validateSchema(obj[propName], propSchema, propPath);
          errors.push(...propResult.errors);
        }
      }
    }

    // Additional properties check
    if (schema.additionalProperties === false && schema.properties) {
      const allowedProps = new Set(Object.keys(schema.properties));
      for (const propName of Object.keys(obj)) {
        if (!allowedProps.has(propName)) {
          errors.push({
            path: path ? `${path}.${propName}` : propName,
            message: `Additional property "${propName}" is not allowed`,
            keyword: 'additionalProperties',
            params: { additionalProperty: propName },
          });
        }
      }
    }
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Validate type
 */
function validateType(data: unknown, expectedType: string): boolean {
  if (expectedType === 'null') {
    return data === null;
  }
  if (expectedType === 'array') {
    return Array.isArray(data);
  }
  if (expectedType === 'integer') {
    return typeof data === 'number' && Number.isInteger(data);
  }
  if (expectedType === 'object') {
    return typeof data === 'object' && data !== null && !Array.isArray(data);
  }
  return typeof data === expectedType;
}

/**
 * Format validation errors for display
 */
export function formatValidationErrors(errors: ValidationError[]): string {
  return errors.map((e) => `${e.path}: ${e.message}`).join('; ');
}

/**
 * Create a validator function for a specific schema
 */
export function createValidator(schema: JSONSchema): (data: unknown) => ValidationResult {
  return (data: unknown) => validateSchema(data, schema);
}

/**
 * @claude-flow/mcp - MCP Server
 *
 * High-performance MCP server implementation
 */

import { EventEmitter } from 'events';
import { platform, arch } from 'os';
import type {
  MCPServerConfig,
  MCPRequest,
  MCPResponse,
  MCPNotification,
  MCPSession,
  MCPTool,
  MCPInitializeParams,
  MCPInitializeResult,
  MCPCapabilities,
  MCPProtocolVersion,
  MCPServerMetrics,
  ITransport,
  TransportType,
  ILogger,
  ToolContext,
} from './types.js';
import { MCPServerError, ErrorCodes } from './types.js';
import { ToolRegistry, createToolRegistry } from './tool-registry.js';
import { SessionManager, createSessionManager } from './session-manager.js';
import { ConnectionPool, createConnectionPool } from './connection-pool.js';
import { ResourceRegistry, createResourceRegistry } from './resource-registry.js';
import { PromptRegistry, createPromptRegistry } from './prompt-registry.js';
import { TaskManager, createTaskManager } from './task-manager.js';
import { createTransport, TransportManager, createTransportManager } from './transport/index.js';
import { RateLimiter, createRateLimiter, type RateLimitConfig } from './rate-limiter.js';
import { SamplingManager, createSamplingManager, type SamplingConfig, type LLMProvider } from './sampling.js';

const DEFAULT_CONFIG: Partial<MCPServerConfig> = {
  name: 'Claude-Flow MCP Server V3',
  version: '3.0.0',
  transport: 'stdio',
  host: 'localhost',
  port: 3000,
  enableMetrics: true,
  enableCaching: true,
  cacheTTL: 10000,
  logLevel: 'info',
  requestTimeout: 30000,
  maxRequestSize: 10 * 1024 * 1024,
};

export interface IMCPServer {
  start(): Promise<void>;
  stop(): Promise<void>;
  registerTool(tool: MCPTool): boolean;
  registerTools(tools: MCPTool[]): { registered: number; failed: string[] };
  getHealthStatus(): Promise<{
    healthy: boolean;
    error?: string;
    metrics?: Record<string, number>;
  }>;
  getMetrics(): MCPServerMetrics;
  getSessions(): MCPSession[];
  getSession(sessionId: string): MCPSession | undefined;
  terminateSession(sessionId: string): boolean;
}

export class MCPServer extends EventEmitter implements IMCPServer {
  private readonly config: MCPServerConfig;
  private readonly toolRegistry: ToolRegistry;
  private readonly sessionManager: SessionManager;
  private readonly resourceRegistry: ResourceRegistry;
  private readonly promptRegistry: PromptRegistry;
  private readonly taskManager: TaskManager;
  private readonly connectionPool?: ConnectionPool;
  private readonly transportManager: TransportManager;
  private readonly rateLimiter: RateLimiter;
  private readonly samplingManager: SamplingManager;
  private transport?: ITransport;
  private running = false;
  private startTime?: Date;
  private startupDuration?: number;
  private currentSession?: MCPSession;
  private resourceSubscriptions: Map<string, Set<string>> = new Map(); // sessionId -> subscribed URIs

  private readonly serverInfo = {
    name: 'Claude-Flow MCP Server V3',
    version: '3.0.0',
  };

  // MCP protocol version — spec-required YYYY-MM-DD date string (#1874).
  // Claude Code's Zod validator rejects any other shape.
  private readonly protocolVersion: MCPProtocolVersion = '2025-11-25';

  // Full MCP 2025-11-25 capabilities
  private capabilities: MCPCapabilities = {
    logging: { level: 'info' },
    tools: { listChanged: true },
    resources: { listChanged: true, subscribe: true },
    prompts: { listChanged: true },
    sampling: {},
  };

  private requestStats = {
    total: 0,
    successful: 0,
    failed: 0,
    totalResponseTime: 0,
  };

  constructor(
    config: Partial<MCPServerConfig>,
    private readonly logger: ILogger,
    private readonly orchestrator?: unknown,
    private readonly swarmCoordinator?: unknown
  ) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config } as MCPServerConfig;

    this.toolRegistry = createToolRegistry(logger);
    this.sessionManager = createSessionManager(logger, {
      maxSessions: 100,
      sessionTimeout: 30 * 60 * 1000,
    });
    this.resourceRegistry = createResourceRegistry(logger, {
      enableSubscriptions: true,
      cacheEnabled: true,
      cacheTTL: 60000,
    });
    this.promptRegistry = createPromptRegistry(logger);
    this.taskManager = createTaskManager(logger, {
      maxConcurrentTasks: 10,
      taskTimeout: 300000,
    });
    this.transportManager = createTransportManager(logger);
    this.rateLimiter = createRateLimiter(logger, {
      requestsPerSecond: 100,
      burstSize: 200,
      perSessionLimit: 50,
    });
    this.samplingManager = createSamplingManager(logger);

    if (this.config.connectionPool) {
      this.connectionPool = createConnectionPool(
        this.config.connectionPool,
        logger,
        this.config.transport
      );
    }

    this.setupEventHandlers();
  }

  /**
   * Get resource registry for external registration
   */
  getResourceRegistry(): ResourceRegistry {
    return this.resourceRegistry;
  }

  /**
   * Get prompt registry for external registration
   */
  getPromptRegistry(): PromptRegistry {
    return this.promptRegistry;
  }

  /**
   * Get task manager for async operations
   */
  getTaskManager(): TaskManager {
    return this.taskManager;
  }

  /**
   * Get rate limiter for configuration
   */
  getRateLimiter(): RateLimiter {
    return this.rateLimiter;
  }

  /**
   * Get sampling manager for LLM provider registration
   */
  getSamplingManager(): SamplingManager {
    return this.samplingManager;
  }

  /**
   * Register an LLM provider for sampling
   */
  registerLLMProvider(provider: LLMProvider, isDefault: boolean = false): void {
    this.samplingManager.registerProvider(provider, isDefault);
  }

  async start(): Promise<void> {
    if (this.running) {
      throw new MCPServerError('Server already running');
    }

    const startTime = performance.now();
    this.startTime = new Date();

    this.logger.info('Starting MCP server', {
      name: this.config.name,
      version: this.config.version,
      transport: this.config.transport,
    });

    try {
      this.transport = createTransport(this.config.transport, this.logger, {
        type: this.config.transport,
        host: this.config.host,
        port: this.config.port,
        corsEnabled: this.config.corsEnabled,
        corsOrigins: this.config.corsOrigins,
        auth: this.config.auth,
        maxRequestSize: String(this.config.maxRequestSize),
        requestTimeout: this.config.requestTimeout,
      } as any);

      this.transport.onRequest(async (request) => {
        return await this.handleRequest(request);
      });

      this.transport.onNotification(async (notification) => {
        await this.handleNotification(notification);
      });

      await this.transport.start();
      await this.registerBuiltInTools();

      this.running = true;
      this.startupDuration = performance.now() - startTime;

      this.logger.info('MCP server started', {
        startupTime: `${this.startupDuration.toFixed(2)}ms`,
        tools: this.toolRegistry.getToolCount(),
      });

      this.emit('server:started', {
        startupTime: this.startupDuration,
        tools: this.toolRegistry.getToolCount(),
      });

    } catch (error) {
      this.logger.error('Failed to start MCP server', { error });
      throw new MCPServerError('Failed to start server', ErrorCodes.INTERNAL_ERROR, { error });
    }
  }

  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }

    this.logger.info('Stopping MCP server');

    try {
      if (this.transport) {
        await this.transport.stop();
        this.transport = undefined;
      }

      this.sessionManager.clearAll();
      this.taskManager.destroy();
      this.resourceSubscriptions.clear();
      this.rateLimiter.destroy();

      if (this.connectionPool) {
        await this.connectionPool.clear();
      }

      this.running = false;
      this.currentSession = undefined;

      this.logger.info('MCP server stopped');
      this.emit('server:stopped');

    } catch (error) {
      this.logger.error('Error stopping MCP server', { error });
      throw error;
    }
  }

  registerTool(tool: MCPTool): boolean {
    return this.toolRegistry.register(tool);
  }

  registerTools(tools: MCPTool[]): { registered: number; failed: string[] } {
    return this.toolRegistry.registerBatch(tools);
  }

  unregisterTool(name: string): boolean {
    return this.toolRegistry.unregister(name);
  }

  async getHealthStatus(): Promise<{
    healthy: boolean;
    error?: string;
    metrics?: Record<string, number>;
  }> {
    try {
      const transportHealth = this.transport
        ? await this.transport.getHealthStatus()
        : { healthy: false, error: 'Transport not initialized' };

      const sessionMetrics = this.sessionManager.getSessionMetrics();
      const poolStats = this.connectionPool?.getStats();

      const metrics: Record<string, number> = {
        registeredTools: this.toolRegistry.getToolCount(),
        totalRequests: this.requestStats.total,
        successfulRequests: this.requestStats.successful,
        failedRequests: this.requestStats.failed,
        totalSessions: sessionMetrics.total,
        activeSessions: sessionMetrics.active,
        ...(transportHealth.metrics || {}),
      };

      if (poolStats) {
        metrics.poolConnections = poolStats.totalConnections;
        metrics.poolIdleConnections = poolStats.idleConnections;
        metrics.poolBusyConnections = poolStats.busyConnections;
      }

      return {
        healthy: this.running && transportHealth.healthy,
        error: transportHealth.error,
        metrics,
      };

    } catch (error) {
      return {
        healthy: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  getMetrics(): MCPServerMetrics {
    const sessionMetrics = this.sessionManager.getSessionMetrics();
    const registryStats = this.toolRegistry.getStats();

    return {
      totalRequests: this.requestStats.total,
      successfulRequests: this.requestStats.successful,
      failedRequests: this.requestStats.failed,
      averageResponseTime: this.requestStats.total > 0
        ? this.requestStats.totalResponseTime / this.requestStats.total
        : 0,
      activeSessions: sessionMetrics.active,
      toolInvocations: Object.fromEntries(
        registryStats.topTools.map((t) => [t.name, t.calls])
      ),
      errors: {},
      lastReset: this.startTime || new Date(),
      startupTime: this.startupDuration,
      uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
    };
  }

  getSessions(): MCPSession[] {
    return this.sessionManager.getActiveSessions();
  }

  getSession(sessionId: string): MCPSession | undefined {
    return this.sessionManager.getSession(sessionId);
  }

  terminateSession(sessionId: string): boolean {
    const result = this.sessionManager.closeSession(sessionId, 'Terminated by server');
    if (this.currentSession?.id === sessionId) {
      this.currentSession = undefined;
    }
    return result;
  }

  private async handleRequest(request: MCPRequest): Promise<MCPResponse> {
    const startTime = performance.now();
    this.requestStats.total++;

    this.logger.debug('Handling request', {
      id: request.id,
      method: request.method,
    });

    // Rate limiting check (skip for initialize)
    if (request.method !== 'initialize') {
      const sessionId = this.currentSession?.id;
      const rateLimitResult = this.rateLimiter.check(sessionId);
      if (!rateLimitResult.allowed) {
        this.requestStats.failed++;
        return {
          jsonrpc: '2.0',
          id: request.id,
          error: {
            code: -32000,
            message: 'Rate limit exceeded',
            data: { retryAfter: rateLimitResult.retryAfter },
          },
        };
      }
      this.rateLimiter.consume(sessionId);
    }

    try {
      if (request.method === 'initialize') {
        return await this.handleInitialize(request);
      }

      const session = this.getOrCreateSession();

      if (!session.isInitialized && request.method !== 'initialized') {
        return this.createErrorResponse(
          request.id,
          ErrorCodes.SERVER_NOT_INITIALIZED,
          'Server not initialized'
        );
      }

      this.sessionManager.updateActivity(session.id);

      const response = await this.routeRequest(request);

      const duration = performance.now() - startTime;
      this.requestStats.successful++;
      this.requestStats.totalResponseTime += duration;

      this.logger.debug('Request completed', {
        id: request.id,
        method: request.method,
        duration: `${duration.toFixed(2)}ms`,
      });

      return response;

    } catch (error) {
      const duration = performance.now() - startTime;
      this.requestStats.failed++;
      this.requestStats.totalResponseTime += duration;

      this.logger.error('Request failed', {
        id: request.id,
        method: request.method,
        error,
      });

      return this.createErrorResponse(
        request.id,
        ErrorCodes.INTERNAL_ERROR,
        error instanceof Error ? error.message : 'Internal error'
      );
    }
  }

  private async handleNotification(notification: MCPNotification): Promise<void> {
    this.logger.debug('Handling notification', { method: notification.method });

    switch (notification.method) {
      case 'initialized':
        this.logger.info('Client initialized notification received');
        break;

      case 'notifications/cancelled':
        this.logger.debug('Request cancelled', notification.params);
        break;

      default:
        this.logger.debug('Unknown notification', { method: notification.method });
    }
  }

  private async handleInitialize(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as unknown as MCPInitializeParams | undefined;

    if (!params) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Invalid params'
      );
    }

    const session = this.sessionManager.createSession(this.config.transport);
    this.sessionManager.initializeSession(session.id, params);
    this.currentSession = session;

    const result: MCPInitializeResult = {
      protocolVersion: this.protocolVersion,
      capabilities: this.capabilities,
      serverInfo: this.serverInfo,
      instructions: 'Claude-Flow MCP Server V3 ready for tool execution',
    };

    this.logger.info('Session initialized', {
      sessionId: session.id,
      clientInfo: params.clientInfo,
    });

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  private async routeRequest(request: MCPRequest): Promise<MCPResponse> {
    switch (request.method) {
      // Tool methods
      case 'tools/list':
        return this.handleToolsList(request);
      case 'tools/call':
        return this.handleToolsCall(request);

      // Resource methods (MCP 2025-11-25)
      case 'resources/list':
        return this.handleResourcesList(request);
      case 'resources/read':
        return this.handleResourcesRead(request);
      case 'resources/subscribe':
        return this.handleResourcesSubscribe(request);
      case 'resources/unsubscribe':
        return this.handleResourcesUnsubscribe(request);

      // Prompt methods (MCP 2025-11-25)
      case 'prompts/list':
        return this.handlePromptsList(request);
      case 'prompts/get':
        return this.handlePromptsGet(request);

      // Task methods (MCP 2025-11-25)
      case 'tasks/status':
        return this.handleTasksStatus(request);
      case 'tasks/cancel':
        return this.handleTasksCancel(request);

      // Completion (MCP 2025-11-25)
      case 'completion/complete':
        return this.handleCompletion(request);

      // Logging (MCP 2025-11-25)
      case 'logging/setLevel':
        return this.handleLoggingSetLevel(request);

      // Sampling (MCP 2025-11-25)
      case 'sampling/createMessage':
        return this.handleSamplingCreateMessage(request);

      // Utility
      case 'ping':
        return {
          jsonrpc: '2.0',
          id: request.id,
          result: { pong: true, timestamp: Date.now() },
        };

      default:
        // Check if it's a direct tool call
        if (this.toolRegistry.hasTool(request.method)) {
          return this.handleToolExecution(request);
        }

        return this.createErrorResponse(
          request.id,
          ErrorCodes.METHOD_NOT_FOUND,
          `Method not found: ${request.method}`
        );
    }
  }

  private handleToolsList(request: MCPRequest): MCPResponse {
    const tools = this.toolRegistry.listTools().map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: this.toolRegistry.getTool(t.name)?.inputSchema,
    }));

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { tools },
    };
  }

  private async handleToolsCall(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as { name: string; arguments?: Record<string, unknown> };

    if (!params?.name) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Tool name is required'
      );
    }

    const context: ToolContext = {
      sessionId: this.currentSession?.id || 'unknown',
      requestId: request.id,
      orchestrator: this.orchestrator,
      swarmCoordinator: this.swarmCoordinator,
    };

    const result = await this.toolRegistry.execute(
      params.name,
      params.arguments || {},
      context
    );

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  private async handleToolExecution(request: MCPRequest): Promise<MCPResponse> {
    const context: ToolContext = {
      sessionId: this.currentSession?.id || 'unknown',
      requestId: request.id,
      orchestrator: this.orchestrator,
      swarmCoordinator: this.swarmCoordinator,
    };

    const result = await this.toolRegistry.execute(
      request.method,
      (request.params as Record<string, unknown>) || {},
      context
    );

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  // ============================================================================
  // Resource Handlers (MCP 2025-11-25)
  // ============================================================================

  private handleResourcesList(request: MCPRequest): MCPResponse {
    const params = request.params as { cursor?: string } | undefined;
    const result = this.resourceRegistry.list(params?.cursor);

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  private async handleResourcesRead(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as { uri: string } | undefined;

    if (!params?.uri) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Resource URI is required'
      );
    }

    try {
      const result = await this.resourceRegistry.read(params.uri);
      return {
        jsonrpc: '2.0',
        id: request.id,
        result,
      };
    } catch (error) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        error instanceof Error ? error.message : 'Resource read failed'
      );
    }
  }

  private handleResourcesSubscribe(request: MCPRequest): MCPResponse {
    const params = request.params as { uri: string } | undefined;
    const sessionId = this.currentSession?.id;

    if (!params?.uri) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Resource URI is required'
      );
    }

    if (!sessionId) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.SERVER_NOT_INITIALIZED,
        'No active session'
      );
    }

    try {
      // Track subscription for this session
      let sessionSubs = this.resourceSubscriptions.get(sessionId);
      if (!sessionSubs) {
        sessionSubs = new Set();
        this.resourceSubscriptions.set(sessionId, sessionSubs);
      }

      const subscriptionId = this.resourceRegistry.subscribe(params.uri, (uri, content) => {
        // Send notification when resource updates
        this.sendNotification('notifications/resources/updated', { uri });
      });

      sessionSubs.add(params.uri);

      return {
        jsonrpc: '2.0',
        id: request.id,
        result: { subscriptionId },
      };
    } catch (error) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INTERNAL_ERROR,
        error instanceof Error ? error.message : 'Subscription failed'
      );
    }
  }

  private handleResourcesUnsubscribe(request: MCPRequest): MCPResponse {
    const params = request.params as { uri: string } | undefined;
    const sessionId = this.currentSession?.id;

    if (!params?.uri) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Resource URI is required'
      );
    }

    if (sessionId) {
      const sessionSubs = this.resourceSubscriptions.get(sessionId);
      if (sessionSubs) {
        sessionSubs.delete(params.uri);
      }
    }

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { success: true },
    };
  }

  // ============================================================================
  // Prompt Handlers (MCP 2025-11-25)
  // ============================================================================

  private handlePromptsList(request: MCPRequest): MCPResponse {
    const params = request.params as { cursor?: string } | undefined;
    const result = this.promptRegistry.list(params?.cursor);

    return {
      jsonrpc: '2.0',
      id: request.id,
      result,
    };
  }

  private async handlePromptsGet(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as { name: string; arguments?: Record<string, string> } | undefined;

    if (!params?.name) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Prompt name is required'
      );
    }

    try {
      const result = await this.promptRegistry.get(params.name, params.arguments);
      return {
        jsonrpc: '2.0',
        id: request.id,
        result,
      };
    } catch (error) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        error instanceof Error ? error.message : 'Prompt get failed'
      );
    }
  }

  // ============================================================================
  // Task Handlers (MCP 2025-11-25)
  // ============================================================================

  private handleTasksStatus(request: MCPRequest): MCPResponse {
    const params = request.params as { taskId?: string } | undefined;

    if (params?.taskId) {
      const task = this.taskManager.getTask(params.taskId);
      if (!task) {
        return this.createErrorResponse(
          request.id,
          ErrorCodes.INVALID_PARAMS,
          `Task not found: ${params.taskId}`
        );
      }
      return {
        jsonrpc: '2.0',
        id: request.id,
        result: task,
      };
    }

    // Return all tasks
    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { tasks: this.taskManager.getAllTasks() },
    };
  }

  private handleTasksCancel(request: MCPRequest): MCPResponse {
    const params = request.params as { taskId: string; reason?: string } | undefined;

    if (!params?.taskId) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Task ID is required'
      );
    }

    const success = this.taskManager.cancelTask(params.taskId, params.reason);

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { success },
    };
  }

  // ============================================================================
  // Completion Handler (MCP 2025-11-25)
  // ============================================================================

  private handleCompletion(request: MCPRequest): MCPResponse {
    const params = request.params as {
      ref: { type: string; name?: string; uri?: string };
      argument: { name: string; value: string };
    } | undefined;

    if (!params?.ref || !params?.argument) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Completion reference and argument are required'
      );
    }

    // Basic completion implementation - can be extended
    const completions: string[] = [];

    if (params.ref.type === 'ref/prompt') {
      // Get prompt argument completions
      const prompt = this.promptRegistry.getPrompt(params.ref.name || '');
      if (prompt?.arguments) {
        for (const arg of prompt.arguments) {
          if (arg.name === params.argument.name) {
            // Could add domain-specific completions here
          }
        }
      }
    } else if (params.ref.type === 'ref/resource') {
      // Get resource URI completions
      const { resources } = this.resourceRegistry.list();
      for (const resource of resources) {
        if (resource.uri.startsWith(params.argument.value)) {
          completions.push(resource.uri);
        }
      }
    }

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: {
        completion: {
          values: completions.slice(0, 10),
          total: completions.length,
          hasMore: completions.length > 10,
        },
      },
    };
  }

  // ============================================================================
  // Logging Handler (MCP 2025-11-25)
  // ============================================================================

  private handleLoggingSetLevel(request: MCPRequest): MCPResponse {
    const params = request.params as { level: string } | undefined;

    if (!params?.level) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'Log level is required'
      );
    }

    // Update capabilities
    this.capabilities.logging = { level: params.level as 'debug' | 'info' | 'warn' | 'error' };

    this.logger.info('Log level updated', { level: params.level });

    return {
      jsonrpc: '2.0',
      id: request.id,
      result: { success: true },
    };
  }

  // ============================================================================
  // Sampling Handler (MCP 2025-11-25)
  // ============================================================================

  private async handleSamplingCreateMessage(request: MCPRequest): Promise<MCPResponse> {
    const params = request.params as {
      messages: Array<{ role: string; content: { type: string; text?: string } }>;
      maxTokens: number;
      systemPrompt?: string;
      modelPreferences?: { hints?: Array<{ name?: string }>; intelligencePriority?: number; speedPriority?: number; costPriority?: number };
      includeContext?: string;
      temperature?: number;
      stopSequences?: string[];
      metadata?: Record<string, unknown>;
    } | undefined;

    if (!params?.messages || !params?.maxTokens) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INVALID_PARAMS,
        'messages and maxTokens are required'
      );
    }

    // Check if sampling is available
    const available = await this.samplingManager.isAvailable();
    if (!available) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INTERNAL_ERROR,
        'No LLM provider available for sampling'
      );
    }

    try {
      const result = await this.samplingManager.createMessage(
        {
          messages: params.messages.map((m) => ({
            role: m.role as 'user' | 'assistant',
            content: m.content as any,
          })),
          maxTokens: params.maxTokens,
          systemPrompt: params.systemPrompt,
          modelPreferences: params.modelPreferences,
          includeContext: params.includeContext as 'none' | 'thisServer' | 'allServers' | undefined,
          temperature: params.temperature,
          stopSequences: params.stopSequences,
          metadata: params.metadata,
        },
        {
          sessionId: this.currentSession?.id || 'unknown',
          serverId: this.serverInfo.name,
        }
      );

      return {
        jsonrpc: '2.0',
        id: request.id,
        result,
      };
    } catch (error) {
      return this.createErrorResponse(
        request.id,
        ErrorCodes.INTERNAL_ERROR,
        error instanceof Error ? error.message : 'Sampling failed'
      );
    }
  }

  // ============================================================================
  // Notification Sender
  // ============================================================================

  private async sendNotification(method: string, params?: Record<string, unknown>): Promise<void> {
    if (this.transport?.sendNotification) {
      await this.transport.sendNotification({
        jsonrpc: '2.0',
        method,
        params,
      });
    }
  }

  private getOrCreateSession(): MCPSession {
    if (this.currentSession) {
      return this.currentSession;
    }

    const session = this.sessionManager.createSession(this.config.transport);
    this.currentSession = session;
    return session;
  }

  private createErrorResponse(
    id: string | number | null,
    code: number,
    message: string
  ): MCPResponse {
    return {
      jsonrpc: '2.0',
      id,
      error: { code, message },
    };
  }

  private async registerBuiltInTools(): Promise<void> {
    this.registerTool({
      name: 'system/info',
      description: 'Get system information',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => ({
        name: this.serverInfo.name,
        version: this.serverInfo.version,
        platform: platform(),
        arch: arch(),
        runtime: 'Node.js',
        uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
      }),
      category: 'system',
    });

    this.registerTool({
      name: 'system/health',
      description: 'Get system health status',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => await this.getHealthStatus(),
      category: 'system',
      cacheable: true,
      cacheTTL: 2000,
    });

    this.registerTool({
      name: 'system/metrics',
      description: 'Get server metrics',
      inputSchema: { type: 'object', properties: {} },
      handler: async () => this.getMetrics(),
      category: 'system',
      cacheable: true,
      cacheTTL: 1000,
    });

    this.registerTool({
      name: 'tools/list-detailed',
      description: 'List all registered tools with details',
      inputSchema: {
        type: 'object',
        properties: {
          category: { type: 'string', description: 'Filter by category' },
        },
      },
      handler: async (input: unknown) => {
        const params = input as { category?: string };
        if (params.category) {
          return this.toolRegistry.getByCategory(params.category);
        }
        return this.toolRegistry.listTools();
      },
      category: 'system',
    });

    this.logger.info('Built-in tools registered', {
      count: 4,
    });
  }

  private setupEventHandlers(): void {
    this.toolRegistry.on('tool:registered', (name) => {
      this.emit('tool:registered', name);
    });

    this.toolRegistry.on('tool:called', (data) => {
      this.emit('tool:called', data);
    });

    this.toolRegistry.on('tool:completed', (data) => {
      this.emit('tool:completed', data);
    });

    this.toolRegistry.on('tool:error', (data) => {
      this.emit('tool:error', data);
    });

    this.sessionManager.on('session:created', (session) => {
      this.emit('session:created', session);
    });

    this.sessionManager.on('session:closed', (data) => {
      this.emit('session:closed', data);
    });

    this.sessionManager.on('session:expired', (session) => {
      this.emit('session:expired', session);
    });
  }
}

export function createMCPServer(
